<?php
/** Proof — tickets: who sees which rows (own / queue / all), the filters against direct SQL over the views as the same member, the internals for queue holders only, the reads an agent's duty starts with. */
require __DIR__ . '/lib.php';
$F = dated(); $W = world(); $T = $F['tickets']; $IT = $F['it'];
$ids = fn (?array $d, string $k = 'tickets') => array_map(fn ($t) => $t['ticket_id'], $d[$k] ?? []);
$sorted = function (array $a) { sort($a); return $a; };
$mine = mkticket(requester_of_member(26), $IT, 'SMOKE p4 Priya asks in IT');       // Priya's own ticket, in the queue Marco holds
echo "1. Who sees which tickets\n";
$all = fn (int $m) => array_map('intval', array_column(sql_as($m, "SELECT ticket_id FROM mcp_tickets WHERE merged_into_id IS NULL"), 'ticket_id'));
$got = $sorted($ids(tdata(26, 'find_tickets', ['limit' => 100])));
ok($got === $sorted($all(26)) && $got !== [] && !array_intersect($got, array_values($T)), 'Priya (a requester) sees her own tickets and none of the dated ones: ' . count($got));
$got = $sorted($ids(tdata(27, 'find_tickets', ['limit' => 100])));
ok($got === $sorted($all(27)) && in_array($T['it5'], $got) && !in_array($T['fac1'], $got), 'Marco sees IT\'s tickets, not Facilities\': ' . count($got));
$got = $sorted($ids(tdata(28, 'find_tickets', ['limit' => 100])));
ok($got === $sorted($all(28)) && in_array($T['fac1'], $got), 'Lena sees both queues\': ' . count($got));
$got = $sorted($ids(tdata(29, 'find_tickets', ['limit' => 100])));
ok($got === $sorted($all(29)) && in_array($T['fac2'], $got) && !in_array($T['it5'], $got), 'Colin sees Facilities and what he follows');
echo "2. find_tickets\n";
$n = num_of($T['it5']);
$d = tdata(27, 'find_tickets', ['q' => $n]);
ok($d === [['ticket_id' => $T['it5'], 'label' => "$n — SMOKE dated it5"]], '`q` = a number: a plain list (ticket_id, "HD-n — subject")');
$d = tdata(27, 'find_tickets', ['q' => 'dated it5']);
ok(is_array($d) && count($d) === 1 && $d[0]['ticket_id'] === $T['it5'], 'words in the subject');
$d = tdata(27, 'find_tickets', ['status_category' => ['open', 'pending'], 'assignee' => 'me', 'limit' => 100]);
$exp = $sorted(array_map('intval', array_column(sql_as(27, "SELECT ticket_id FROM mcp_tickets WHERE assignee_member_id = 27 AND status_category IN ('open','pending') AND merged_into_id IS NULL"), 'ticket_id')));
ok($sorted($ids($d)) === $exp && count($exp) >= 2, 'status_category + assignee=me = direct SQL as Marco (' . count($exp) . ')');
$d = tdata(27, 'find_tickets', ['assignee' => 'none', 'queue_id' => $IT, 'limit' => 100]);
ok(count($d['tickets']) >= 2 && !array_filter($d['tickets'], fn ($t) => $t['assignee_member_id'] !== null), 'assignee=none: unassigned only');
$d = tdata(28, 'find_tickets', ['needs_reply' => true, 'limit' => 100]);
ok($sorted($ids($d)) === $sorted(array_map('intval', array_column(sql_as(28, "SELECT ticket_id FROM mcp_tickets WHERE needs_reply AND merged_into_id IS NULL"), 'ticket_id'))) && in_array($T['it5'], $ids($d)), 'needs_reply');
$d = tdata(28, 'find_tickets', ['sla_state' => 'breached', 'status_category' => ['new', 'open', 'pending', 'on_hold'], 'limit' => 100]);
ok($sorted($ids($d)) === $sorted(array_map('intval', array_column(sql_as(28, "SELECT ticket_id FROM mcp_tickets WHERE sla_state = 'breached' AND status_category IN " . OPEN_SQL . " AND merged_into_id IS NULL"), 'ticket_id'))) && count($d['tickets']) >= 2, 'sla_state=breached (' . count($d['tickets']) . ')');
$d = tdata(28, 'find_tickets', ['reopened' => true, 'limit' => 100]);
ok($ids($d) === [$T['it3']], 'reopened: it3 only');
$d = tdata(28, 'find_tickets', ['priority' => ['urgent', 'high'], 'channel' => 'email', 'limit' => 100]);
ok($sorted(array_map(fn ($t) => $t['ticket_id'], $d['tickets'])) === $sorted(array_map('intval', array_column(sql_as(28, "SELECT ticket_id FROM mcp_tickets WHERE priority IN ('urgent','high') AND channel = 'email' AND merged_into_id IS NULL"), 'ticket_id'))), 'priority[] + channel');
$d = tdata(28, 'find_tickets', ['created_from' => (new DateTimeImmutable('-15 days'))->format('Y-m-d'), 'limit' => 100]);
ok($sorted($ids($d)) === $sorted(array_map('intval', array_column(sql_as(28, "SELECT ticket_id FROM mcp_tickets WHERE created_at >= now()::date - 15 AND merged_into_id IS NULL"), 'ticket_id'))), 'created_from');
$d = tdata(28, 'find_tickets', ['sort' => 'oldest', 'limit' => 3]);
ok($d['tickets'][0]['created_at'] <= $d['tickets'][1]['created_at'] && count($d['tickets']) === 3, 'sort=oldest and limit');
ok(isset($d['tickets'][0]['created_at_local']) && isset($d['tickets'][0]['label']), 'rows carry local times and the label');
echo "3. get_ticket and the internals\n";
$d = tdata(27, 'get_ticket', ['ticket_id' => $T['it5']]);
ok($d['ticket']['number'] === $n && $d['can_see_internals'] === true && isset($d['sla_targets']) && count($d['sla_targets']) === 2 && $d['time']['minutes'] === 30 && isset($d['viewers']), 'Marco: the ticket with SLA targets, time logged (30 minutes) and viewers');
ok($d['requester']['display_name'] === 'SMOKE Jo' && $d['requester']['email'] === 'jo@customer.invalid', 'the requester with address (a queue holder)');
$d2 = tdata(27, 'get_ticket', ['number' => substr($n, 3)]);
ok($d2['ticket']['ticket_id'] === $T['it5'], 'by the digits of the number');
$d = tdata(26, 'get_ticket', ['ticket_id' => $mine]);
ok(!isset($d['error']) && $d['can_see_internals'] === false && !isset($d['sla_targets']) && !isset($d['time']) && !isset($d['viewers']), 'Priya on her own ticket: no SLA targets, no time, no viewers');
ok(tool(26, 'get_ticket', ['ticket_id' => $T['it5']])['error'] && tool(29, 'get_ticket', ['ticket_id' => $T['it5']])['error'], 'a ticket they may not see: refused (Priya, Colin)');
$d = tdata(29, 'get_ticket', ['ticket_id' => $W['t_jo2']]);
ok($d['ticket']['ticket_id'] === $W['t_jo2'] && $d['can_see_internals'] === false && count($d['followers']) >= 1, 'Colin follows t_jo2: he sees it, not its internals; the followers list');
ok(tool(27, 'get_ticket', [])['error'], 'no id and no number: asked which');
echo "4. The conversation\n";
q("INSERT INTO messages (ticket_id, kind, author_requester_id, body_text, channel) VALUES (:t, 'public_reply', :r, 'SMOKE p4 hello from Priya', 'web')", ['t' => $mine, 'r' => requester_of_member(26)]);
q("INSERT INTO messages (ticket_id, kind, author_member_id, body_text) VALUES (:t, 'internal_note', 27, 'SMOKE p4 internal note')", ['t' => $mine]);
q("INSERT INTO messages (ticket_id, kind, author_member_id, body_text) VALUES (:t, 'public_reply', 27, 'SMOKE p4 reply from Marco')", ['t' => $mine]);
$d = tdata(26, 'ticket_conversation', ['ticket_id' => $mine]);
ok(count($d['messages']) === 2 && !str_contains(json_encode($d), 'internal note'), 'Priya reads the two public messages and never the note');
$d = tdata(27, 'ticket_conversation', ['ticket_id' => $mine]);
ok(count($d['messages']) === 3 && $d['messages'][1]['kind'] === 'internal_note' && $d['messages'][0]['author_requester_name'] === 'SMOKE Priya', 'Marco reads three in order, the note between them');
$d = tdata(27, 'ticket_conversation', ['ticket_id' => $mine, 'kind' => 'internal_note']);
ok(count($d['messages']) === 1, 'kind=internal_note');
$d = tdata(27, 'ticket_conversation', ['ticket_id' => $mine, 'since' => '2100-01-01']);
ok($d['messages'] === [], 'since a date in the future: nothing');
ok(tool(26, 'ticket_conversation', ['ticket_id' => $T['it5']])['error'], 'a conversation she may not see: refused');
$d = tdata(27, 'ticket_viewers', ['ticket_id' => $T['it5']]);
ok($d['viewers'] === [] && tool(26, 'ticket_viewers', ['ticket_id' => $mine])['error'], 'ticket_viewers: queue holders (a requester is refused)');
echo "5. The agent's reads\n";
$d = tdata(27, 'my_queue', []);
$mineIds = $sorted($ids($d, 'assigned'));
ok($mineIds === $sorted(array_map('intval', array_column(sql_as(27, "SELECT ticket_id FROM mcp_tickets WHERE assignee_member_id = 27 AND status_category IN " . OPEN_SQL . " AND merged_into_id IS NULL"), 'ticket_id'))) && $d['counts']['assigned_open'] === count($mineIds), 'my_queue: Marco\'s open tickets = direct SQL (' . count($mineIds) . ')');
ok($d['assigned'][0]['needs_reply'] === true && $d['assigned'][0]['ticket_id'] === $T['it5'], 'needs-reply first');
$un = (int) val_as(27, "SELECT count(*) FROM mcp_tickets t WHERE t.merged_into_id IS NULL AND t.assignee_member_id IS NULL AND t.status_category IN " . OPEN_SQL . " AND t.queue_id IN (SELECT queue_id FROM mcp_queues WHERE mine)");
ok($d['counts']['unassigned_in_my_queues'] === $un && count($d['unassigned']) === min($un, 25) && $un >= 3, "the unassigned tickets of his queues ($un)");
ok(tdata(27, 'my_queue', ['include_unassigned' => false])['unassigned'] === [], 'include_unassigned=false');
$d = tdata(26, 'my_queue', []);
ok($d['assigned'] === [] && $d['unassigned'] === [], 'a requester has nothing to do next');
$d = tdata(27, 'triage_queue', []);
$new = $sorted(array_map('intval', array_column(sql_as(27, "SELECT ticket_id FROM mcp_tickets WHERE status_category = 'new' AND merged_into_id IS NULL"), 'ticket_id')));
ok($sorted($ids($d)) === $new && count($new) >= 3, 'triage_queue: the new ones, oldest first (' . count($new) . ')');
$jo = array_values(array_filter($d['tickets'], fn ($t) => $t['ticket_id'] === $W['t_jo']))[0] ?? null;
ok($jo !== null && str_contains((string) $jo['first_message'], 'it is on fire') && $jo['same_requester_open'] !== [], 'with the first message\'s excerpt and the requester\'s other open tickets');
ok(tool(26, 'triage_queue', [])['error'], 'a requester: refused');
$d = tdata(28, 'sla_at_risk', ['state' => 'breached']);
ok(count($d['tickets']) >= 2 && !array_filter($d['tickets'], fn ($t) => $t['minutes_left'] >= 0 || $t['sla_state'] !== 'breached'), 'sla_at_risk: breached ones, minutes left negative');
ok($d['tickets'][0]['sla_next_due_at'] <= $d['tickets'][1]['sla_next_due_at'], 'soonest due first');
ok(tool(26, 'sla_at_risk', [])['error'], 'a requester: refused');
$d = tdata(27, 'stale_tickets', ['days' => 7]);
$stale = $sorted(array_map('intval', array_column(sql_as(27, "SELECT ticket_id FROM mcp_tickets WHERE merged_into_id IS NULL AND status_category IN " . OPEN_SQL . " AND last_activity_at < now() - interval '7 days'"), 'ticket_id')));
ok($sorted($ids($d)) === $stale && count($stale) >= 1 && $d['tickets'][0]['idle_days'] >= 7, 'stale_tickets days=7 = direct SQL (' . count($stale) . ')');
$d = tdata(27, 'similar_tickets', ['ticket_id' => $T['it5']]);
ok(!in_array($T['it5'], $ids($d)) && count($d['tickets']) >= 3 && $d['tickets'][0]['score'] >= $d['tickets'][count($d['tickets']) - 1]['score'], 'similar_tickets: not itself, the same requester\'s first, scored');
$d = tdata(27, 'similar_tickets', ['text' => 'dated it5 printer', 'open_only' => true]);
ok(count($d['tickets']) >= 1 && !array_filter($d['tickets'], fn ($t) => in_array($t['status_category'], ['solved', 'closed'])), 'by free text, open only');
$d = tdata(27, 'tickets_changed_since', ['since' => '2100-01-01']);
ok($d['tickets'] === [], 'tickets_changed_since the future: nothing');
$d = tdata(27, 'tickets_changed_since', ['since' => '2020-01-01', 'limit' => 100]);
ok($sorted($ids($d)) === $sorted($all(27)) , 'since 2020: everything Marco sees');
echo "6. Counts and aging\n";
$d = tdata(28, 'ticket_counts', ['group_by' => 'status_category']);
ok($d['total'] === count($all(28)) && array_sum(array_column($d['groups'], 'n')) === $d['total'], 'ticket_counts by category: the total = what Lena sees (' . $d['total'] . ')');
$d = tdata(28, 'ticket_counts', ['group_by' => 'queue', 'open_only' => true]);
$g = array_column($d['groups'], 'n', 'group');
ok(($g['SMOKE IT help'] ?? 0) === (int) val_as(28, "SELECT count(*) FROM mcp_tickets WHERE queue_id = :q AND merged_into_id IS NULL AND status_category IN " . OPEN_SQL, ['q' => $IT]), 'by queue, open only: IT\'s count = direct SQL');
$d = tdata(26, 'ticket_counts', ['group_by' => 'queue']);
ok($d['total'] === count($all(26)), 'Priya counts her own');
ok(tool(28, 'ticket_counts', ['group_by' => 'colour'])['error'] && tool(28, 'ticket_counts', ['group_by' => 'status', 'period' => 'month', 'from' => '2026-02-01', 'to' => '2026-01-01'])['error'], 'an unknown grouping and a backwards period: refused');
$d = tdata(28, 'ticket_counts', ['group_by' => 'priority', 'period' => 'last_30_days']);
ok($d['total'] === (int) val_as(28, "SELECT count(*) FROM mcp_tickets WHERE merged_into_id IS NULL AND created_at >= (now() AT TIME ZONE 'UTC')::date - 29"), 'period=last_30_days counts by created date');
$d = tdata(27, 'backlog_aging', []);
ok($d['total'] === (int) val_as(27, "SELECT count(*) FROM mcp_tickets WHERE merged_into_id IS NULL AND status_category IN " . OPEN_SQL) && array_column($d['queues'], 'queue_id') === [$IT], 'backlog_aging: Marco\'s open total, IT only (' . $d['total'] . ')');
ok(array_keys($d['queues'][0]['buckets']) === ['today', 'd1_3', 'd4_7', 'd8_30', 'older'], 'five buckets in order');
ok(tool(26, 'backlog_aging', [])['error'], 'a requester: refused');
finish();
